class MaxStack {
    list<int> dll;
    map<int, vector<list<int>::iterator>> map;
public:
    MaxStack() {}

    void push(int x) {
        dll.push_front(x);
        map[x].push_back(dll.begin());
    }

    int pop() {
        int x = dll.front();
        dll.pop_front();
        map[x].pop_back();
        if (map[x].empty()) map.erase(x);
        return x;
    }

    int top() {
        return dll.front();
    }

    int peekMax() {
        return map.rbegin()->first;
    }

    int popMax() {
        int maxVal = map.rbegin()->first;
        auto it = map[maxVal].back();
        map[maxVal].pop_back();
        if (map[maxVal].empty()) map.erase(maxVal);
        dll.erase(it);
        return maxVal;
    }
};

class MaxStack {
    class Node {
        int val, id;
        Node prev, next;
        Node(int v, int i) { val = v; id = i; }
    }
    private Node head, tail;
    private PriorityQueue<Node> heap;
    private Set<Integer> deleted;
    private int idCounter = 0;

    public MaxStack() {
        head = new Node(0, 0);
        tail = new Node(0, 0);
        head.next = tail;
        tail.prev = head;
        heap = new PriorityQueue<>((a, b) -> a.val != b.val ? b.val - a.val : b.id - a.id);
        deleted = new HashSet<>();
    }

    public void push(int x) {
        idCounter++;
        Node node = new Node(x, idCounter);
        Node pred = tail.prev;
        pred.next = node;
        node.prev = pred;
        node.next = tail;
        tail.prev = node;
        heap.offer(node);
    }

    private void cleanTail() {
        while (tail.prev != head && deleted.contains(tail.prev.id)) {
            Node node = tail.prev;
            node.prev.next = tail;
            tail.prev = node.prev;
        }
    }

    public int pop() {
        cleanTail();
        Node node = tail.prev;
        node.prev.next = tail;
        tail.prev = node.prev;
        deleted.add(node.id);
        return node.val;
    }

    public int top() {
        cleanTail();
        return tail.prev.val;
    }

    private void cleanHeap() {
        while (!heap.isEmpty() && deleted.contains(heap.peek().id)) {
            heap.poll();
        }
    }

    public int peekMax() {
        cleanHeap();
        return heap.peek().val;
    }

    public int popMax() {
        cleanHeap();
        Node node = heap.poll();
        deleted.add(node.id);
        node.prev.next = node.next;
        node.next.prev = node.prev;
        return node.val;
    }
}

class Node {
    constructor(val, id) {
        this.val = val;
        this.id = id;
        this.prev = null;
        this.next = null;
    }
}

var MaxStack = function() {
    this.head = new Node(0, 0);
    this.tail = new Node(0, 0);
    this.head.next = this.tail;
    this.tail.prev = this.head;
    this.stack = []; // [Node]
};

/** 
 * @param {number} x
 * @return {void}
 */
MaxStack.prototype.push = function(x) {
    const node = new Node(x, this.stack.length);
    const pred = this.tail.prev;
    pred.next = node;
    node.prev = pred;
    node.next = this.tail;
    this.tail.prev = node;
    this.stack.push(node);
};

/** 
 * @return {number}
 */
MaxStack.prototype.pop = function() {
    const node = this.tail.prev;
    node.prev.next = this.tail;
    this.tail.prev = node.prev;
    const idx = this.stack.indexOf(node);
    if (idx !== -1) this.stack.splice(idx, 1);
    return node.val;
};

/** 
 * @return {number}
 */
MaxStack.prototype.top = function() {
    return this.tail.prev.val;
};

/** 
 * @return {number}
 */
MaxStack.prototype.peekMax = function() {
    let maxVal = -Infinity;
    let curr = this.head.next;
    while (curr !== this.tail) {
        if (curr.val > maxVal) maxVal = curr.val;
        curr = curr.next;
    }
    return maxVal;
};

/** 
 * @return {number}
 */
MaxStack.prototype.popMax = function() {
    let maxVal = -Infinity;
    let maxNode = null;
    let curr = this.tail.prev;
    while (curr !== this.head) {
        if (curr.val > maxVal) {
            maxVal = curr.val;
            maxNode = curr;
        }
        curr = curr.prev;
    }
    maxNode.prev.next = maxNode.next;
    maxNode.next.prev = maxNode.prev;
    const idx = this.stack.indexOf(maxNode);
    if (idx !== -1) this.stack.splice(idx, 1);
    return maxVal;
};
